const $=s=>document.querySelector(s);
const html=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shapes={back:'<path d="m14 6-6 6 6 6M8 12h13"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',check:'<path d="m5 12 4 4L20 5"/>',audio:'<path d="m11 4-6 5H2v6h3l6 5V4zm4 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',flip:'<path d="M20 7v5h-5M4 17v-5h5M20 12a8 8 0 0 0-14-5M4 12a8 8 0 0 0 14 5"/>',play:'<path d="m9 5 11 7-11 7z"/>',pen:'<path d="m16 3 5 5L9 20H4v-5zm-2 2 5 5M3 23h18"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',book:'<path d="M12 5C8 2 4 3 2 4v15c4-2 7-1 10 1 3-2 6-3 10-1V4c-3-1-6-2-10 1zM12 5v15"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',spark:'<path d="m12 3 3 6 6 3-6 3-3 6-3-6-6-3 6-3z"/>'};
const svg=k=>`<svg viewBox="0 0 24 24" aria-hidden="true">${shapes[k]||shapes.book}</svg>`;
const allWords=vocabulary.flatMap(u=>u.words);
const byId=new Map(allWords.map(w=>[w.id,w]));
let progress={},storageError=false;
try{const p=JSON.parse(localStorage.getItem('wordly-memory-v1')||'{}');if(p&&typeof p==='object')for(const[id,r]of Object.entries(p))if(byId.has(id)&&['known','unknown'].includes(r?.status))progress[id]=r;}catch{storageError=true}
let unit=null,session=null,query='',topic='',listFilter='all';
const status=w=>progress[w.id]?.status||'new';
const statusLabel=s=>({known:'Bilaman',unknown:'Bilmayman',new:'Yangi'}[s]);
const counts=ws=>ws.reduce((c,w)=>(c[status(w)]++,c),{known:0,unknown:0,new:0});
function storeProgress(){try{localStorage.setItem('wordly-memory-v1',JSON.stringify(progress));storageError=false}catch{storageError=true;notify('Brauzer xotirasi ishlamayapti. Natijalar faqat shu seansda saqlanadi.')}}
function setRating(w,rating){if(!byId.has(w.id)||!['known','unknown'].includes(rating))return;const old=progress[w.id];progress[w.id]={status:rating,updated:Date.now(),attempts:(old?.attempts||0)+1};storeProgress()}
function route(){session=null;const match=location.hash.match(/^#(?:unit-|unit\/EVU-)(\d{1,3})$/);unit=match?vocabulary.find(u=>u.number===+match[1])||null:null;listFilter='all';render();window.scrollTo(0,0)}
function go(n){const hash=n?'#unit-'+n:'#units';if(location.hash===hash)route();else location.hash=hash}
function render(){document.documentElement.lang='uz';document.title=unit?`${unit.number}. ${unit.title} — WORDLY`:'WORDLY — So‘z yodlash';$('#app').innerHTML=`<div class="workspace ${session?'session-workspace':''}">${session?sessionView():unit?unitView():homeView()}${storageError?'<p class="storage-warning" role="status">Xotira bilan bog‘liq muammo: natijalar brauzer yopilganda yo‘qolishi mumkin.</p>':''}</div>`;bind();}
function homeView(){const c=counts(allWords);return `<header class="app-header"><a class="wordmark" href="#units"><span class="logo">w</span>WORDLY<span class="wordmark-note">so‘z yodlash</span></a><span class="header-total">${allWords.length.toLocaleString('en')} ta so‘z</span></header><section class="intro"><div class="eyebrow">SIZNING LUG‘ATINGIZ</div><h1>English Vocabulary in Use</h1><p>Pre-intermediate & Intermediate <span>·</span> 100 ta unit</p></section><div class="home-progress"><div><span class="dot known"></span><strong>${c.known}</strong> bilaman</div><div><span class="dot unknown"></span><strong>${c.unknown}</strong> bilmayman</div><div><span class="dot new"></span><strong>${c.new}</strong> yangi</div><div class="mini-track" aria-label="${c.known} ta so‘z yodlangan"><i style="width:${c.known/allWords.length*100}%"></i></div></div><div class="searchbar"><label class="search-field">${svg('search')}<input id="search" placeholder="Unit yoki so‘z qidirish…" aria-label="Unit yoki so‘z qidirish" value="${html(query)}"></label><select id="topic" aria-label="Mavzu"><option value="">Barcha mavzular</option>${[...new Set(vocabulary.map(u=>u.group))].map(g=>`<option ${topic===g?'selected':''} value="${html(g)}">${html(g)}</option>`).join('')}</select></div><div id="catalog">${catalog()}</div><footer>Kitobdagi qalin so‘z va iboralar asosida. Natijalar shu brauzerda saqlanadi.</footer>`}
function matchingUnits(){const q=normalise(query);return vocabulary.filter(u=>(!topic||u.group===topic)&&(!q||normalise(`${u.number} ${u.title} ${u.group}`).includes(q)||u.words.some(w=>normalise(w.en+' '+w.uz).includes(q))))}
function catalog(){const list=matchingUnits();return `<div class="section-heading"><h2>Unitlar</h2><span>${list.length} ta unit</span></div><div class="unit-grid">${list.map(u=>{const c=counts(u.words);return `<a class="unit-tile" href="#unit-${u.number}"><div class="tile-top"><span class="unit-number">${String(u.number).padStart(2,'0')}</span>${c.known===u.words.length?`<span class="complete-mark">${svg('check')}</span>`:`<span class="tile-count">${u.words.length} ta so‘z</span>`}</div><p class="unit-category">${html(u.group)}</p><h3>${html(u.title)}</h3><div class="tile-bottom"><div class="mini-track"><i style="width:${c.known/u.words.length*100}%"></i></div><span>${c.known}/${u.words.length}</span>${svg('arrow')}</div></a>`}).join('')||'<div class="empty">Hech narsa topilmadi. Boshqa so‘z bilan qidiring.</div>'}</div>`}
function stats(ws){const c=counts(ws);return `<div class="unit-stats">${[['known','check'],['unknown','close'],['new','spark']].map(([s,i])=>`<div class="stat ${s}">${svg(i)}<strong>${c[s]}</strong><span>${statusLabel(s)}</span></div>`).join('')}</div>`}
function unitView(){const ws=unit.words,selected=ws.filter(w=>listFilter==='all'||status(w)===listFilter);return `<a class="back-link" href="#units">${svg('back')} English Vocabulary in Use</a><section class="unit-banner"><span class="big-number">${unit.number}</span><div><p>${html(unit.group)}</p><h1>${html(unit.title)}</h1><span>${ws.length} ta so‘z</span></div></section>${stats(ws)}<div class="start-actions"><button class="button primary start-button" data-action="start">${svg('play')}Boshlash · ${selected.length} ta</button><button class="button secondary" data-action="write">${svg('pen')}Yozib mashq qilish</button></div><div class="filter-tabs" role="group" aria-label="So‘z holati">${[['all','Hammasi'],['known','Bilaman'],['unknown','Bilmayman'],['new','Yangi']].map(([s,l])=>`<button class="${listFilter===s?'active':''}" data-filter="${s}" aria-pressed="${listFilter===s}">${l}</button>`).join('')}</div><div class="word-list">${selected.map(w=>`<article class="word-row"><span class="word-icon ${status(w)}">${svg(status(w)==='known'?'check':status(w)==='unknown'?'close':'spark')}</span><div class="word-copy"><h2>${html(w.en)}</h2><p>${html(w.uz)}</p></div><span class="word-status ${status(w)}">${statusLabel(status(w))}</span><button class="icon-button" data-sound="${w.id}" aria-label="${html(w.en)} talaffuzini tinglash">${svg('audio')}</button></article>`).join('')||'<div class="empty">Bu bo‘limda hali so‘z yo‘q. «Hammasi»ni tanlang.</div>'}</div><div class="unit-pagination">${unit.number>1?`<a href="#unit-${unit.number-1}">← Oldingi unit</a>`:'<span></span>'}${unit.number<100?`<a href="#unit-${unit.number+1}">Keyingi unit →</a>`:''}</div>`}
function startSession(mode='flash',ids){const ws=ids?unit.words.filter(w=>ids.includes(w.id)):unit.words.filter(w=>listFilter==='all'||status(w)===listFilter);if(!ws.length)return notify('Bu bo‘limda so‘z yo‘q. Boshqa bo‘limni tanlang.');session={mode,words:[...ws],index:0,flipped:false,ratings:{},checked:false,answer:'',direction:'uz',correct:false};render();window.scrollTo(0,0);focusAnswer()}
function sessionView(){const s=session,w=s.words[s.index],c=Object.values(s.ratings).reduce((a,r)=>(a[r]++,a),{known:0,unknown:0});if(!w)return finishView(c);return `<header class="session-header"><button class="icon-button close-session" data-action="exit" aria-label="Unitga qaytish">${svg('close')}</button><div class="session-title"><h1>${unit.number}. ${html(unit.title)}</h1><div class="mini-track"><i style="width:${s.index/s.words.length*100}%"></i></div></div><span class="session-count">${s.index+1}<span>/${s.words.length}</span></span></header><div class="session-counts"><span class="known">${svg('check')}<strong>${c.known}</strong> bilaman</span><span class="unknown">${svg('close')}<strong>${c.unknown}</strong> bilmayman</span></div>${s.mode==='flash'?flashView(w):writeView(w)}<p class="keyboard-hint">${s.mode==='flash'?'<kbd>Space</kbd> aylantirish <span>·</span> <kbd>←</kbd> bilmayman <span>·</span> <kbd>→</kbd> bilaman <span>·</span> <kbd>S</kbd> tinglash':'Javobni yozing va Enter bosing.'}</p>`}
function flashView(w){const s=session;return `<button id="flashcard" class="flashcard ${s.flipped?'flipped':''}" data-action="flip" aria-pressed="${s.flipped}" aria-label="${html(s.flipped?w.uz:w.en)}. ${s.flipped?'Inglizcha so‘zni':'Tarjimani'} ko‘rsatish"><span class="flashcard-inner"><span id="card-front" class="card-face card-front" aria-hidden="${s.flipped}"><span class="card-meta"><span>ENGLISH</span><span class="card-state ${status(w)}">${statusLabel(status(w))}</span></span><span class="card-word" lang="en">${html(w.en)}</span><span class="card-hint">${svg('flip')} Tarjimani ko‘rish uchun bosing</span></span><span id="card-back" class="card-face card-back" aria-hidden="${!s.flipped}"><span class="card-meta"><span>O‘ZBEKCHA</span><span class="card-state ${status(w)}">${statusLabel(status(w))}</span></span><span class="card-word" lang="uz">${html(w.uz)}</span><span class="card-original" lang="en">${html(w.en)}</span><span class="card-hint">${svg('flip')} So‘zga qaytish uchun bosing</span></span></span></button><div class="flash-controls"><div><button class="round-button unknown" data-action="unknown" aria-label="Bilmayman">${svg('close')}</button><span>Bilmayman</span></div><div><button class="round-button subtle" data-action="flip" aria-label="Kartochkani aylantirish">${svg('flip')}</button><span>Aylantirish</span></div><div><button class="round-button subtle" data-sound="${w.id}" aria-label="Talaffuzni tinglash">${svg('audio')}</button><span>Tinglash</span></div><div><button class="round-button known" data-action="known" aria-label="Bilaman">${svg('check')}</button><span>Bilaman</span></div></div>`}
function writeView(w){const s=session;return `<div class="direction-tabs"><button data-direction="uz" class="${s.direction==='uz'?'active':''}" ${s.checked?'disabled':''}>English → O‘zbekcha</button><button data-direction="en" class="${s.direction==='en'?'active':''}" ${s.checked?'disabled':''}>O‘zbekcha → English</button></div><section class="write-card"><span class="eyebrow">TARJIMASINI YOZING</span><h2 lang="${s.direction==='uz'?'en':'uz'}">${html(s.direction==='uz'?w.en:w.uz)}</h2><form id="answer-form"><label class="sr-only" for="answer">Tarjimasi</label><input id="answer" placeholder="${s.direction==='uz'?'O‘zbekcha':'Inglizcha'} javobni yozing…" value="${html(s.answer)}" autocomplete="off" autocapitalize="off" spellcheck="false" ${s.checked?'disabled':''}>${!s.checked?'<button class="button primary" type="submit">Tekshirish</button>':''}</form>${s.checked?`<div class="answer-feedback ${s.correct?'known':'unknown'}" role="status"><strong>${s.correct?'To‘g‘ri!':'To‘g‘ri javob:'}</strong><span>${html(s.direction==='uz'?w.uz:w.en)}</span>${!s.correct?'<small>Bu so‘z «Bilmayman» bo‘limiga saqlandi.</small>':''}</div><button class="button primary" data-action="next">Davom etish ${svg('arrow')}</button>`:''}</section>`}
function resultFor(known,total){if(total<=0)return{tier:'empty',ratio:0};const count=Math.max(0,Math.min(known,total)),ratio=count/total;return count*100>=total*90?{tier:'excellent',title:'Barakalla!',message:'Ajoyib natija! So‘zlarni juda yaxshi bilasiz.',ratio}:count*100>=total*70?{tier:'satisfactory',title:'Yaxshi, qoniqarli',message:'Yaxshi harakat! Bilmagan so‘zlarni yana bir marta takrorlang.',ratio}:{tier:'needs-practice',title:'Yomon',message:'Yodlash kerak, bo‘lmasa darsda tik turasan!',ratio}}
function finishView(c){const total=session.words.length;if(!total)return `<a class="back-link" href="#unit-${unit.number}" data-action="exit">Unitga qaytish</a><div class="empty">Mashq uchun so&#8216;z yo&#8216;q.</div>`;const r=resultFor(c.known,total),percent=(total>0?Math.floor(c.known*1000/total)/10:0).toLocaleString('uz-UZ',{maximumFractionDigits:1});return `<a class="back-link" href="#unit-${unit.number}" data-action="exit">${svg('back')} Unitga qaytish</a><section class="finish-card result-card result-${r.tier}" aria-labelledby="result-title">${r.tier==='excellent'?`<span class="result-confetti" aria-hidden="true">${Array.from({length:12},(_,i)=>`<i style="--particle:${i}"></i>`).join('')}</span>`:''}<span class="finish-icon" aria-hidden="true">${svg(r.tier==='excellent'?'check':r.tier==='satisfactory'?'spark':'close')}</span><div class="eyebrow">${unit.number}. ${html(unit.title)}</div><p class="completion-label">Mashq tugadi. Shu urinish natijasi.</p><div class="result-summary" role="status"><h1 id="result-title" tabindex="-1">${r.title}</h1><div class="result-percent">${percent}<span>%</span></div><p class="result-count">${c.known} / ${total} ta so‘zni bildingiz</p><p class="result-message">${r.message}</p></div><div class="session-counts"><span class="known">${svg('check')} ${c.known} bilaman</span><span class="unknown">${svg('close')} ${c.unknown} bilmayman</span></div>${c.unknown?`<button class="button primary" data-action="retry">Bilmaganlarni takrorlash · ${c.unknown}</button>`:'<p class="finish-message">Barcha so‘zlarni bildingiz!</p>'}<button class="button secondary" data-action="exit">So‘zlar ro‘yxatiga qaytish</button></section>`}
function flip(){if(!session||session.mode!=='flash'||!session.words[session.index])return;session.flipped=!session.flipped;const card=$('#flashcard');if(!card)return;const w=session.words[session.index];card.classList.toggle('flipped',session.flipped);card.setAttribute('aria-pressed',String(session.flipped));card.setAttribute('aria-label',`${session.flipped?w.uz:w.en}. ${session.flipped?'Inglizcha so‘zni':'Tarjimani'} ko‘rsatish`);$('#card-front')?.setAttribute('aria-hidden',String(session.flipped));$('#card-back')?.setAttribute('aria-hidden',String(!session.flipped));}
function rate(r){if(!session||session.mode!=='flash')return;const w=session.words[session.index];if(!w)return;setRating(w,r);session.ratings[w.id]=r;advance()}
function advance(){if(!session)return;session.index++;session.flipped=false;session.checked=false;session.answer='';render();focusAnswer()}
function normalise(s){return String(s).toLocaleLowerCase().replace(/[‘’ʻʼ`'’]/g,'').replace(/[^\p{L}\p{N}\s]/gu,' ').replace(/\s+/g,' ').trim()}
function acceptedAnswers(w,direction){const target=direction==='uz'?w.uz:w.en;return [...new Set([target,...target.split(/\s+yoki\s+|\s*\/\s*/)].map(normalise).filter(Boolean))]}
function checkAnswer(value){const s=session;if(!s||s.checked||!s.words[s.index])return;if(!value.trim())return notify('Avval javob yozing.');const w=s.words[s.index];s.answer=value;s.correct=acceptedAnswers(w,s.direction).includes(normalise(value));s.checked=true;const r=s.correct?'known':'unknown';setRating(w,r);s.ratings[w.id]=r;render();$('[data-action="next"]')?.focus()}
function focusAnswer(){if(session?.mode==='write'&&!session.checked)$('#answer')?.focus()}
function speak(id){const w=byId.get(id);if(!w)return;if(!('speechSynthesis' in window)||typeof SpeechSynthesisUtterance==='undefined')return notify('Bu brauzerda ovozli talaffuz mavjud emas.');speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(w.en);utterance.lang='en-GB';utterance.rate=.85;utterance.onerror=e=>{if(!['canceled','interrupted'].includes(e.error))notify('Ovoz ijro etilmadi. Qurilmangizdagi inglizcha ovozni tekshiring.')};speechSynthesis.speak(utterance)}
let notificationTimer;function notify(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(notificationTimer);notificationTimer=setTimeout(()=>el.classList.remove('show'),4000)}
function action(name){switch(name){case'start':startSession();break;case'write':startSession('write');break;case'flip':flip();break;case'known':rate('known');break;case'unknown':rate('unknown');break;case'next':if(session?.checked)advance();break;case'exit':session=null;render();break;case'retry':{const ids=Object.keys(session.ratings).filter(id=>session.ratings[id]==='unknown');startSession(session.mode,ids);break}}}
function bind(){const search=$('#search');if(search)search.oninput=()=>{query=search.value;$('#catalog').innerHTML=catalog()};const select=$('#topic');if(select)select.onchange=()=>{topic=select.value;$('#catalog').innerHTML=catalog()};const form=$('#answer-form');if(form)form.onsubmit=e=>{e.preventDefault();checkAnswer($('#answer').value)};let down;const card=$('#flashcard');if(card){card.onpointerdown=e=>{down={x:e.clientX,y:e.clientY}};card.onpointerup=e=>{if(down&&Math.abs(e.clientX-down.x)>70&&Math.abs(e.clientY-down.y)<80){e.preventDefault();swipeUntil=Date.now()+300;rate(e.clientX>down.x?'known':'unknown')}down=null};card.onpointercancel=()=>down=null}}
let swipeUntil=0;
document.addEventListener('click',e=>{if(Date.now()<swipeUntil)return;const sound=e.target.closest('[data-sound]');if(sound){speak(sound.dataset.sound);return}const filter=e.target.closest('[data-filter]');if(filter){listFilter=filter.dataset.filter;render();return}const direction=e.target.closest('[data-direction]');if(direction&&!session?.checked){session.direction=direction.dataset.direction;session.answer='';render();focusAnswer();return}const button=e.target.closest('[data-action]');if(button){e.preventDefault();action(button.dataset.action)}});
document.addEventListener('keydown',e=>{if(!session)return;const typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if(e.key==='Escape'){e.preventDefault();action('exit');return}if(typing)return;if(session.mode==='write'&&session.checked&&e.key==='Enter'){e.preventDefault();advance();return}if(session.mode!=='flash')return;if(e.code==='Space'){e.preventDefault();flip()}else if(e.key==='ArrowLeft'||e.key==='1'){e.preventDefault();rate('unknown')}else if(e.key==='ArrowRight'||e.key==='2'){e.preventDefault();rate('known')}else if(e.key.toLowerCase()==='s'){e.preventDefault();const w=session.words[session.index];if(w)speak(w.id)}});
window.addEventListener('hashchange',route);
route();
